  "e": "Stable angina is most likely; chest tightness on climbing stairs resolving within 5 minutes of rest reflects fixed atherosclerotic plaque producing ischaemia at predictable exertion thresholds.<br><br>Treatment includes lifestyle modification, antiplatelet therapy, statin, beta-blocker, and short-acting nitrate. Long-acting nitrates and calcium channel blockers add symptomatic benefit. Revascularisation considered for refractory symptoms.<br><br>Unstable angina (option A) is rest pain or crescendo; acute MI (option C) is prolonged with troponin rise; pericarditis (option D) is positional, distinct from stable predictable exertional angina.<br><br><em>(First Aid for USMLE Step 1)</em>"
