  "e": "Beta-blockers are first-line for angina prophylaxis; reduced heart rate and contractility decrease myocardial oxygen demand reducing ischaemic episodes during exertion.<br><br>Metoprolol, bisoprolol, or atenolol are commonly used. Side effects include bradycardia, fatigue, hypotension, and bronchospasm in asthma. Avoid abrupt discontinuation due to rebound ischaemia. Calcium channel blockers are alternatives.<br><br>Aspirin (option A) is antiplatelet for events; nitrates (option C) are symptomatic; statins (option D) are lipid-lowering, none replacing beta-blocker first-line angina prophylactic role.<br><br><em>(First Aid for USMLE Step 1)</em>"
