  "e": "Calcium channel blockers reduce angina through coronary vasodilation; dihydropyridines (amlodipine, felodipine) and non-dihydropyridines (verapamil, diltiazem) provide symptomatic relief.<br><br>Verapamil and diltiazem reduce heart rate and AV conduction. Amlodipine has minimal cardiac effects with peripheral vasodilation. Side effects include peripheral oedema, headache, flushing, and bradycardia (non-dihydropyridines). Useful in vasospastic angina.<br><br>Aspirin (option A) is antiplatelet; nitrates (option B) are symptomatic short-acting; statin (option D) is lipid-lowering, distinct from calcium channel blocker symptomatic angina prophylactic mechanism.<br><br><em>(First Aid for USMLE Step 1)</em>"
