  "c": "Stable angina",
  "d": "Variant angina",
  "ans": "C",
  "e": "Ranolazine is novel anti-anginal for refractory symptoms; this late sodium current inhibitor reduces angina without affecting heart rate or blood pressure.<br><br>Indicated when standard agents (beta-blockers, calcium channel blockers, nitrates) inadequate or contraindicated. Side effects include constipation, dizziness, nausea, and QT prolongation. Drug interactions with CYP3A4 inhibitors require dose adjustment in clinical practice.<br><br>Beta-blockers (option B) reduce heart rate; calcium channel blockers (option C) affect blood pressure; nitrates (option D) reduce blood pressure, none being haemodynamically neutral like ranolazine.<br><br><em>(First Aid for USMLE Step 1)</em>"
