  "e": "Pre-renal azotaemia from over-diuresis is likely cause of worsening renal function; aggressive diuresis reduces renal perfusion producing azotaemia.<br><br>Reduce diuretic dose, ensure adequate hydration, and reassess volume status. Cardiorenal syndrome reflects bidirectional heart-kidney dysfunction. SGLT2 inhibitors provide renal protection. Avoid nephrotoxins (NSAIDs, contrast). Multidisciplinary cardiology-nephrology approach optimises management for refractory cases.<br><br>Renal artery stenosis (option A) presents differently with ACE inhibitor; intrinsic renal disease (option B) is independent; obstructive uropathy (option D) is anatomical, distinct from over-diuresis pre-renal azotaemia.<br><br><em>(First Aid for USMLE Step 1)</em>"
