  "d": "Anticoagulation",
  "ans": "D",
  "e": "Mitral stenosis severity reflects valve area; mean gradient and pulmonary artery pressure complement assessment.<br><br>Severe mitral stenosis has valve area under 1.5 cm2, mean gradient over 5-10 mmHg (depending on heart rate), and elevated pulmonary artery pressure. Echocardiography characterises severity. Treatment includes diuretics for symptoms, anticoagulation for atrial fibrillation, percutaneous balloon mitral valvuloplasty, or surgical valve replacement clinically.<br><br>Increased valve area (option A) is opposite; reduced left atrial pressure (option C) is opposite; absent symptoms (option D) is asymptomatic, distinct from severe MS reduced valve area-elevated gradient pattern.<br><br><em>(First Aid for USMLE Step 1)</em>"
