  "e": "Pregnancy worsens mitral stenosis symptoms; increased blood volume and cardiac output during pregnancy unmask or worsen symptoms.<br><br>Echocardiography characterises severity pre-pregnancy when possible. Symptomatic severe mitral stenosis warrants intervention before pregnancy. Percutaneous balloon mitral valvuloplasty during pregnancy for refractory symptoms. Beta-blockers and diuretics for symptom control. Anticoagulation for atrial fibrillation requires specialist input.<br><br>Improves symptoms (option B) is opposite; no effect on symptoms (option C) is incorrect; only acute MR (option D) is differential, distinct from pregnancy worsening MS through volume and output increase.<br><br><em>(First Aid for USMLE Step 1)</em>"
