  "e": "Opening snap occurs from sudden tensing of stenotic mitral valve; pliable rheumatic mitral valve produces this characteristic high-pitched sound after S2.<br><br>Opening snap is best heard at apex with diaphragm of stethoscope. Distance from S2 to opening snap inversely correlates with severity (shorter A2-OS interval indicates severer stenosis). Loud S1 and mid-diastolic rumble complete classical mitral stenosis auscultatory pattern. Calcified valves may lose opening snap.<br><br>Closure of normal mitral valve (option A) produces S1; aortic valve closure (option C) produces A2; pulmonary valve closure (option D) produces P2, distinct from opening snap stenotic mitral valve characteristic finding.<br><br><em>(First Aid for USMLE Step 1)</em>"
