  "e": "Mitral valve area under 1.0 cm2 is critical mitral stenosis; severe outflow obstruction causes significant haemodynamic compromise.<br><br>Severity grading: normal valve area 4-6 cm2, mild MS 1.5-2.5 cm2, moderate 1.0-1.5 cm2, severe under 1.5 cm2 (or under 1.0 cm2 in some classifications), critical under 1.0 cm2. Symptoms typically develop with valve area under 2 cm2. Treatment with PBMV or valve replacement for severe symptomatic disease.<br><br>Area over 2 cm2 (option B) is mild; area 1.5-2 cm2 (option C) is mild-moderate; area 1.0-1.5 cm2 (option D) is moderate, distinct from critical MS valve area under 1.0 cm2 cutoff.<br><br><em>(First Aid for USMLE Step 1)</em>"
