  "e": "Pulmonary congestion in mitral stenosis worsens with tachycardia; reduced diastolic filling time worsens transmitral gradient and elevates left atrial pressure.<br><br>Atrial fibrillation with rapid ventricular response common precipitant. Beta-blockers, non-dihydropyridine calcium channel blockers, and digoxin slow heart rate improving filling. Avoid sympathomimetics. Pregnancy, infection, and exercise commonly precipitate decompensation. Treatment of underlying mitral stenosis (PBMV or surgery) addresses cause.<br><br>Bradycardia (option A) prolongs filling improving symptoms; normal sinus rhythm (option C) is baseline; controlled atrial fibrillation (option D) is acceptable, distinct from tachycardia worsening MS through reduced filling time.<br><br><em>(First Aid for USMLE Step 1)</em>"
