  "e": "Subcutaneous nodules are firm painless nodules over extensor surfaces; bony prominences (elbows, wrists, knees, occiput) are typical sites.<br><br>Less common Jones criterion than polyarthritis or carditis. Subcutaneous nodules are pea-sized, firm, painless, and mobile. Resolution over weeks. Other Jones criteria include fever, arthralgia, elevated acute phase reactants, prolonged PR interval, and evidence of preceding strep infection. Erythema marginatum is non-pruritic transient rash.<br><br>Tender warm nodules (option B) suggest inflammation; pruritic vesicles (option C) is differential; pigmented macules (option D) is differential, distinct from rheumatic fever subcutaneous painless extensor nodules.<br><br><em>(First Aid for USMLE Step 1)</em>"
