  "e": "Tetralogy of Fallot is most common cyanotic congenital heart disease; four anomalies (VSD, pulmonary stenosis, overriding aorta, RV hypertrophy) produce right-to-left shunt and cyanosis.<br><br>Boot-shaped heart on chest X-ray reflects right ventricular hypertrophy and absent main pulmonary artery shadow. Tet spells (hypercyanotic episodes) require knee-chest position, oxygen, morphine, and beta-blockers. Surgical complete repair in infancy provides excellent outcomes. Late complications include right heart failure and arrhythmias.<br><br>Transposition of great arteries (option B) is uncommon; tricuspid atresia (option C) is uncommon; total anomalous pulmonary venous return (option D) is uncommon, none surpassing tetralogy of Fallot frequency in cyanotic CHD.<br><br><em>(First Aid for USMLE Step 1)</em>"
