  "e": "Beta-blockers are first-line for rate control in AF; metoprolol, bisoprolol, or atenolol provide effective rate control in most patients.<br><br>Non-dihydropyridine calcium channel blockers (verapamil, diltiazem) alternative when beta-blockers contraindicated. Avoid verapamil and diltiazem in HFrEF. Digoxin alternative or addition for refractory cases. Target heart rate under 110/min in lenient strategy. Long-term follow-up is essential.<br><br>Aspirin alone (option B) is antiplatelet not rate control; statin (option C) is lipid-lowering; nitrate (option D) is symptomatic, distinct from beta-blocker AF rate control first-line.<br><br><em>(First Aid for USMLE Step 1)</em>"
